 static final TaskReminderActions.Transport DEFAULT_TRANSPORT=(method,path,body)->TaskManagementActivity.httpWithTimeout(method,path,body,path.startsWith("/api/work-state")?25000:45000);static TaskReminderActions.Transport transport=DEFAULT_TRANSPORT;
 static final ExecutorService IO=Executors.newSingleThreadExecutor(),COMMAND_IO=Executors.newSingleThreadExecutor();static JSONObject state=new JSONObject();static String owner="";static long anchor,mono,fullMono;static String error="";static boolean busy;static boolean refreshing;static final List<Done> waiters=new ArrayList<>();
 interface Done{void done(JSONObject value,String error);}
 static String scope(Context c){return DirectConfig.scope(c);}
 static JSONObject snapshot(Context c){if(!scope(c).equals(owner)){state=new JSONObject();owner=scope(c);}return state;}
 static JSONObject own(Context c){JSONArray a=snapshot(c).optJSONArray("own");return a==null?null:a.optJSONObject(0);}
 static long now(){return anchor+Math.max(0,SystemClock.elapsedRealtime()-mono);}
 static void refreshFresh(Context c,Done done){if(refreshing){refresh(c,(r,e)->refreshFresh(c,done));return;}fullMono=SystemClock.elapsedRealtime()-30001;refresh(c,done);}
 static void refresh(Context c,Done done){if(Boolean.getBoolean("adib.testing")&&transport==DEFAULT_TRANSPORT){if(done!=null)done.done(null,"");return;}if(DirectRuntime.enabled()){if(done!=null)done.done(null,"İş taymeri üçün server rejiminə keçin");return;}if(done!=null)waiters.add(done);if(refreshing)return;if(snapshot(c).has("serverNow")&&SystemClock.elapsedRealtime()-mono<2000&&SystemClock.elapsedRealtime()-fullMono<30000){List<Done> callbacks=new ArrayList<>(waiters);waiters.clear();for(Done callback:callbacks)callback.done(state,"");return;}refreshing=true;final Context app=c.getApplicationContext();final String scoped=scope(app);IO.execute(()->{JSONObject result=null;String problem="";try{result=transport.request("GET","/api/work-state"+(!state.optBoolean("tasksLoading")&&state.has("revision")&&SystemClock.elapsedRealtime()-fullMono<30000?"?revision="+state.optLong("revision"):""),null);}catch(Exception e){problem=networkMessage(e);}final JSONObject r=result;final String err=problem;new Handler(Looper.getMainLooper()).post(()->{refreshing=false;List<Done> callbacks=new ArrayList<>(waiters);waiters.clear();if(!scoped.equals(scope(app))){for(Done callback:callbacks)callback.done(null,"Profil dəyişib");return;}if(r!=null){owner=scoped;if(!r.optBoolean("unchanged")&&(!state.has("revision")||r.optLong("revision")>=state.optLong("revision"))){state=r;fullMono=SystemClock.elapsedRealtime();}if(r.optLong("serverNow")>=now()||!state.has("serverNow")){anchor=r.optLong("serverNow");mono=SystemClock.elapsedRealtime();}error="";clearAcknowledged(app,scoped,state);WorkTimerService.sync(app,own(app));}else error=err;for(Done callback:callbacks)callback.done(r==null?null:state,err);});});}
 static android.content.SharedPreferences commandPrefs(Context c,String scoped){return c.getSharedPreferences("adib_work_command_"+DirectRuntime.scopeHash(scoped),0);}
 static boolean sameCommand(JSONObject a,JSONObject b){if(a==null||b==null)return false;Set<String> keys=new HashSet<>();for(Iterator<String> i=a.keys();i.hasNext();)keys.add(i.next());for(Iterator<String> i=b.keys();i.hasNext();)keys.add(i.next());keys.remove("operationId");for(String key:keys)if(!String.valueOf(a.opt(key)).equals(String.valueOf(b.opt(key))))return false;return true;}
 static JSONObject pendingCommand(Context c,String scoped){try{return new JSONObject(commandPrefs(c,scoped).getString("pending","{}"));}catch(Exception e){return new JSONObject();}}
 static JSONObject acknowledged(JSONObject snapshot,JSONObject command){if(snapshot==null||command==null)return null;String token=command.optString("operationId");if(token.isEmpty())return null;JSONArray rows=snapshot.optJSONArray("sessions");if(rows==null)rows=snapshot.optJSONArray("own");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject session=rows.optJSONObject(i);if(session==null)continue;String actor=snapshot.optJSONObject("actor")==null?"":snapshot.optJSONObject("actor").optString("id");if(!actor.isEmpty()&&!actor.equals(session.optString("actorId")))continue;if((command.optString("action").equals("start")||command.optString("action").equals("continue"))?token.equals(session.optString("startOperation")):token.equals(session.optString("lastOperation")))return session;}return null;}
 static void clearAcknowledged(Context c,String scoped,JSONObject snapshot){JSONObject command=pendingCommand(c,scoped),session=acknowledged(snapshot,command);if(session!=null){WorkTimerOwnership.confirm(c,command,session);commandPrefs(c,scoped).edit().remove("pending").commit();}}
 static String networkMessage(Exception e){return OfflineNetwork.error(e)||String.valueOf(e.getMessage()).toLowerCase(Locale.ROOT).contains("timeout")?"Serverin cavabı gecikir. Əməliyyat yoxlanılır; yeni seans təkrar yaradılmır.":String.valueOf(e.getMessage());}
 static void acceptAction(Context c,JSONObject result){JSONObject session=result.optJSONObject("session");if(session==null)return;try{JSONObject st=snapshot(c);JSONArray previous=st.optJSONArray("sessions"),rows=new JSONArray();if(previous!=null)for(int i=0;i<previous.length();i++){JSONObject row=previous.optJSONObject(i);if(row!=null&&!row.optString("id").equals(session.optString("id"))&&!(result.optJSONObject("savedSession")!=null&&row.optString("id").equals(result.optJSONObject("savedSession").optString("id"))))rows.put(row);}if(result.optJSONObject("savedSession")!=null)rows.put(result.optJSONObject("savedSession"));rows.put(session);st.put("sessions",rows);JSONArray own=new JSONArray();String actor=st.optJSONObject("actor")==null?session.optString("actorId"):st.optJSONObject("actor").optString("id");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(actor.equals(row.optString("actorId"))&&!row.optString("status").equals("saved"))own.put(row);}st.put("own",own);if(result.has("revision"))st.put("revision",result.optLong("revision"));if(result.has("serverNow")){anchor=result.optLong("serverNow");mono=SystemClock.elapsedRealtime();st.put("serverNow",anchor);}if(result.has("totalMinutes")){JSONObject totals=st.optJSONObject("totals");if(totals==null)totals=new JSONObject();totals.put(session.optString("taskId"),result.opt("totalMinutes"));st.put("totals",totals);}error="";WorkTimerService.sync(c.getApplicationContext(),own(c));}catch(Exception ignored){}}
 static void refreshForStart(Context c,Done done){JSONObject cached=snapshot(c);if(cached.has("actor")&&cached.has("serverNow")&&SystemClock.elapsedRealtime()-mono<30000){done.done(cached,"");return;}final String scoped=scope(c);COMMAND_IO.execute(()->{JSONObject reply=null;String problem="";try{if(!scoped.equals(scope(c)))throw new Exception("Profil dəyişib");reply=transport.request("GET","/api/work-state",null);if(reply==null||!reply.has("actor")||reply.optLong("serverNow",0)<=0)throw new Exception("Taymerin vəziyyətini yoxlamaq alınmadı");}catch(Exception e){reply=null;problem=networkMessage(e);}final JSONObject r=reply;final String err=problem;new Handler(Looper.getMainLooper()).post(()->{if(!scoped.equals(scope(c))){done.done(null,"Profil dəyişib");return;}if(r==null){error=err;done.done(null,err);return;}if(!state.has("revision")||r.optLong("revision")>=state.optLong("revision")){state=r;owner=scoped;anchor=r.optLong("serverNow");mono=SystemClock.elapsedRealtime();fullMono=mono;clearAcknowledged(c,scoped,state);}error="";WorkTimerService.sync(c.getApplicationContext(),own(c));done.done(state,"");});});}
 static void action(Context c,JSONObject body,Done done){final String scoped=scope(c);if(busy){done.done(null,"Əvvəlki əməliyyatın cavabı gözlənilir");return;}final JSONObject sent;try{JSONObject prior=pendingCommand(c,scoped);sent=new JSONObject(body.toString());if(prior.has("operationId")){if(!sameCommand(prior,sent)){done.done(null,"Əvvəlki əməliyyat hələ təsdiqlənməyib. Taymerin vəziyyətini yeniləyin.");return;}sent.put("operationId",prior.optString("operationId"));}if(!sent.optString("operationId").matches("[a-zA-Z0-9-]{8,100}"))sent.put("operationId",UUID.randomUUID().toString());if(!commandPrefs(c,scoped).edit().putString("pending",sent.toString()).commit())throw new Exception("Əməliyyatı cihazda saxlamaq alınmadı");}catch(Exception e){done.done(null,e.getMessage());return;}busy=true;error="Server cavabı gözlənilir…";COMMAND_IO.execute(()->{JSONObject result=null,recovered=null;String problem="";boolean rejected=false;try{if(!scoped.equals(scope(c)))throw new Exception("Profil dəyişib");result=transport.request("POST","/api/work-timer",sent);}catch(Exception e){problem=networkMessage(e);rejected=e instanceof TaskManagementActivity.ApiError&&((TaskManagementActivity.ApiError)e).status>=400&&((TaskManagementActivity.ApiError)e).status<500;if((!rejected||(e instanceof TaskManagementActivity.ApiError&&((TaskManagementActivity.ApiError)e).code.equals("WORK_ALREADY_ACTIVE")))&&scoped.equals(scope(c)))try{recovered=transport.request("GET","/api/work-state",null);JSONObject session=acknowledged(recovered,sent);if(!rejected&&session!=null)result=new JSONObject().put("ok",true).put("session",session).put("serverNow",recovered.optLong("serverNow")).put("reconciled",true);}catch(Exception ignored){}}final JSONObject r=result,fresh=recovered;final String err=problem;final boolean failed=rejected;new Handler(Looper.getMainLooper()).post(()->{busy=false;if(!scoped.equals(scope(c))){done.done(null,"Profil dəyişib");return;}if(r==null){if(failed)commandPrefs(c,scoped).edit().remove("pending").commit();if(fresh!=null&&(!state.has("revision")||fresh.optLong("revision")>=state.optLong("revision"))){state=fresh;owner=scoped;anchor=fresh.optLong("serverNow");mono=SystemClock.elapsedRealtime();fullMono=mono;WorkTimerService.sync(c.getApplicationContext(),own(c));}error=err;done.done(null,err);return;}WorkTimerOwnership.confirm(c,sent,r.optJSONObject("session"));commandPrefs(c,scoped).edit().remove("pending").commit();if(fresh!=null){state=fresh;owner=scoped;}acceptAction(c,r);done.done(r,"");fullMono=0;refresh(c,null);});});}
 static JSONObject command(String action,JSONObject s)throws JSONException{return new JSONObject().put("action",action).put("sessionId",s.optString("id")).put("revision",s.optInt("revision"));}
 static double totalMinutes(JSONObject snapshot,String taskId){JSONObject totals=snapshot.optJSONObject("totals");double value=totals==null?0:totals.optDouble(taskId,0);return Double.isFinite(value)&&value>=0?value:0;}
 static JSONObject confirmationTimes(JSONObject original,String start,String end)throws Exception{JSONObject values=new JSONObject();String a=start.trim(),b=end.trim();if(!a.equals(at(original.optLong("startedAt"))))values.put("startedAt",parseExact(a));if(!b.equals(at(original.optLong("endedAt"))))values.put("endedAt",parseExact(b));return values;}
 static long parseExact(String value)throws Exception{java.text.ParsePosition position=new java.text.ParsePosition(0);java.util.Date parsed=format().parse(value,position);if(parsed==null||position.getIndex()!=value.length()||!format().format(parsed).equals(value))throw new Exception("Tarix formatını yoxlayın");return parsed.getTime();}
 static String duration(long sec){sec=Math.max(0,sec);return String.format(Locale.ROOT,"%02d:%02d:%02d",sec/3600,sec/60%60,sec%60);}
 static long elapsed(JSONObject s){return Math.max(0,((s.optString("status").equals("running")?now():s.optLong("endedAt"))-s.optLong("startedAt"))/1000);}
 static java.text.SimpleDateFormat format(){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.ROOT);f.setLenient(false);f.setTimeZone(TimeZone.getTimeZone("Asia/Baku"));return f;}
 static String at(long ms){return format().format(new Date(ms));}
 static void open(Context c,JSONObject session){open(c,session,false);}
 static void open(Context c,JSONObject session,boolean stop){if(session!=null&&(stop||session.optString("status").equals("pending"))&&(Build.VERSION.SDK_INT<23||Settings.canDrawOverlays(c))){WorkTimerService.show(c,session);return;}Intent i=new Intent(c,WorkTimerActivity.class);if(session!=null)i.putExtra("session",session.toString());i.putExtra("stop",stop);if(!(c instanceof Activity))i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);}
 static void setup(Activity a){IO.execute(()->{String error="";try{transport.request("POST","/api/work-schema",new JSONObject());}catch(Exception e){error=e.getMessage();}final String message=error.isEmpty()?"Vaxt sahələri hazırdır":error;a.runOnUiThread(()->Toast.makeText(a,message,Toast.LENGTH_LONG).show());});}
 static void textIfChanged(TextView view,String value){if(value==null)value="";if(!value.contentEquals(view.getText()))view.setText(value);}
 static void attach(Activity a,LinearLayout parent,JSONObject task){if(task==null||task.optString("id").isEmpty())return;boolean dark=a.getSharedPreferences(TaskManagementActivity.mainPreferencesName(a),0).getBoolean("dark_theme",false);LinearLayout box=new LinearLayout(a);box.setTag("compact-work-timer");box.setBackgroundColor(android.graphics.Color.TRANSPARENT);box.setOrientation(1);box.setPadding(0,8,0,0);TextView label=new TextView(a);label.setText("İş taymeri");label.setTextSize(11);TextView total=new TextView(a);Button control=new Button(a);control.setText("İşə başla");Button history=new Button(a);history.setText("İş seansları");TextView status=new TextView(a);label.setTextColor(HybridUi.text(dark));total.setTextColor(HybridUi.text(dark));status.setTextColor(HybridUi.muted(dark));WorkUi.compact(control,dark,false);WorkUi.compact(history,dark,false);total.setTextSize(12);status.setTextSize(11);LinearLayout heading=new LinearLayout(a);heading.setGravity(android.view.Gravity.CENTER_VERTICAL);heading.addView(label,new LinearLayout.LayoutParams(-2,-2));box.addView(heading);heading.addView(total,new LinearLayout.LayoutParams(0,-2,1));LinearLayout actions=new LinearLayout(a);actions.addView(control,new LinearLayout.LayoutParams(0,Math.round(44*a.getResources().getDisplayMetrics().density),1));actions.addView(history,new LinearLayout.LayoutParams(0,Math.round(44*a.getResources().getDisplayMetrics().density),1));box.addView(actions);box.addView(status);parent.addView(box);final Handler h=new Handler(Looper.getMainLooper());Runnable paint=()->{JSONObject st=snapshot(a),own=own(a);boolean same=own!=null&&own.optString("taskId").equals(task.optString("id"));JSONObject totals=st.optJSONObject("totals");textIfChanged(total,"Ümumi vaxt: "+totalMinutes(st,task.optString("id"))+" dəq"+(same?" · "+duration(elapsed(own)):""));textIfChanged(control,same?(own.optString("status").equals("running")?"Dayandır":"Vaxtı təsdiqlə"):"İşə başla");textIfChanged(status,error);status.setVisibility(error.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);control.setEnabled(!task.optBoolean("completed")||same);};control.setOnClickListener(v->{JSONObject s=own(a);if(s!=null){open(a,s,s.optString("taskId").equals(task.optString("id"))&&s.optString("status").equals("running"));return;}start(a,task);});history.setOnClickListener(v->{StringBuilder text=new StringBuilder();JSONArray sessions=snapshot(a).optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);if(s!=null&&s.optString("taskId").equals(task.optString("id")))text.append(s.optString("worker")).append(" · ").append(at(s.optLong("startedAt"))).append(" → ").append(s.optLong("endedAt")>0?at(s.optLong("endedAt")):"İş gedir").append(" · ").append(duration(elapsed(s))).append("\n\n");}new AlertDialog.Builder(a).setTitle("İş seansları").setMessage(text.length()==0?"Seans yoxdur":text.toString()).setPositiveButton("Bağla",null).show();});Runnable tick=new Runnable(){public void run(){if(!box.isAttachedToWindow())return;paint.run();h.postDelayed(this,1000);}};box.addOnAttachStateChangeListener(new android.view.View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(android.view.View v){h.post(tick);}public void onViewDetachedFromWindow(android.view.View v){h.removeCallbacksAndMessages(null);}});paint.run();refresh(a,(r,e)->paint.run());}
 static void startFromReminder(Activity a,JSONObject reference){refresh(a,(r,e)->{if(r==null){Toast.makeText(a,e,Toast.LENGTH_LONG).show();return;}JSONArray tasks=r.optJSONArray("tasks");if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t!=null&&t.optString("id").equals(reference.optString("id"))){start(a,t);return;}}Toast.makeText(a,"Tapşırıq mövcud deyil və ya giriş yoxdur",Toast.LENGTH_LONG).show();});}
 static void start(Activity a,JSONObject task){refreshForStart(a,(r,e)->{if(r==null){Toast.makeText(a,e,Toast.LENGTH_LONG).show();return;}if(own(a)!=null){open(a,own(a));return;}JSONArray assigned=task.optJSONArray("tapsirildi");if(assigned==null||assigned.length()==0){Toast.makeText(a,"Əvvəlcə Tapsirildi sahəsində əməkdaşı seçin və yadda saxlayın",Toast.LENGTH_LONG).show();return;}List<String> names=new ArrayList<>();for(int i=0;i<assigned.length();i++)names.add(assigned.optString(i));JSONObject actor=r.optJSONObject("actor");int selected=Math.max(0,names.indexOf(actor==null?"":actor.optString("assignee")));Spinner pick=new Spinner(a);pick.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,names));pick.setSelection(selected);AlertDialog d=new AlertDialog.Builder(a).setTitle("İşləyən əməkdaş — Tapsirildi").setView(pick).setNegativeButton("Ləğv et",null).setPositiveButton("İşə başla",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{d.getButton(-1).setEnabled(false);action(a,new JSONObject().put("action","start").put("id",task.optString("id")).put("worker",pick.getSelectedItem().toString()),(result,err)->{d.getButton(-1).setEnabled(true);if(result==null){Toast.makeText(a,err,Toast.LENGTH_LONG).show();JSONObject existing=own(a);if(existing!=null){d.dismiss();open(a,existing);}return;}d.dismiss();open(a,result.optJSONObject("session"));});}catch(Exception ex){Toast.makeText(a,ex.getMessage(),Toast.LENGTH_LONG).show();}}));d.show();});}
 static JSONArray events(Context c,JSONObject filters){JSONArray out=new JSONArray(),sessions=snapshot(c).optJSONArray("sessions"),tasks=snapshot(c).optJSONArray("tasks");Map<String,JSONObject> byId=new HashMap<>();if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t!=null)byId.put(t.optString("id"),t);}if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);if(s==null)continue;boolean match=true;for(String[] pair:new String[][]{{"workSource","sourceKey"},{"workState","status"},{"workWorker","worker"},{"workTask","taskId"}}){String value=filters.optString(pair[0]);if(!value.isEmpty()&&!value.equals(s.optString(pair[1])))match=false;}if(!match)continue;try{JSONObject original=byId.get(s.optString("taskId")),t=original==null?new JSONObject():new JSONObject(original.toString());t.put("id","work:"+s.optString("id")).put("workSession",s).put("sourceKey",s.optString("sourceKey")).put("title",(s.optString("status").equals("running")?"▶ ":s.optString("status").equals("pending")?"◷ ":"✓ ")+s.optString("title")+" · "+s.optString("worker")).put("date",iso(s.optLong("startedAt"))).put("dateEnd",iso(Math.max(s.optLong("startedAt")+1000,s.optLong("endedAt")>0?s.optLong("endedAt"):now()))).put("completed",original!=null&&original.optBoolean("completed")).put("display","work").put("workSource",s.optString("sourceKey")).put("workWorker",s.optString("worker")).put("workState",s.optString("status")).put("workTask",s.optString("taskId")).remove("completedAt");out.put(t);}catch(Exception ignored){}}return out;}
 static String iso(long ms){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date(ms));}
